TON:
VAR Delay : TON; END_VAR
Delay(IN := StartPB, PT := T#5s);
Lamp := Delay.Q;

TOF:
VAR OffDelay : TOF; END_VAR
OffDelay(IN := Running, PT := T#10s);
Fan := OffDelay.Q;

TP:
VAR Pulse : TP; END_VAR
Pulse(IN := StartPB, PT := T#2s);
Horn := Pulse.Q;

R_TRIG:
VAR Edge : R_TRIG; END_VAR
Edge(CLK := StartPB);
IF Edge.Q THEN Count := Count + 1; END_IF;

F_TRIG:
VAR Fall : F_TRIG; END_VAR
Fall(CLK := Running);
IF Fall.Q THEN Stops := Stops + 1; END_IF;

CTU:
VAR Parts : CTU; END_VAR
Parts(CU := PartPresent, R := ResetPB, PV := 10);
BatchDone := Parts.Q;

CTD:
VAR Remaining : CTD; END_VAR
Remaining(CD := PartPresent, LD := LoadPB, PV := 10);
Empty := Remaining.Q;
